// 8K HDTV SoC with 12 AXI masters, 5 IOMMUs, a 4x4 mesh NoC, 8 LPDDR5 ports and an APB peripheral bus
// Do not edit: change the spec and run socgen again.
// ============================================================================
`ifndef TV8K_SOC_MESH_PKG_SV
`define TV8K_SOC_MESH_PKG_SV
package tv8k_soc_mesh_pkg;
  // ---------------- sizes ----------------
  localparam int NM  = 12;       // AXI masters
  localparam int NS  = 10;       // NoC slave ports
  localparam int NCH = 8;       // interleaved memory channels (ports 0..NCH-1)
  localparam int S_DEF = NS;       // decode miss: DECERR from the NoC default slave
  localparam int MESH_ROWS = 4, MESH_COLS = 4;
  localparam int NI_CYCLES = 1, ROUTER_CYCLES = 1, LINK_CYCLES = 1;
  localparam real CLK_PERIOD_NS = 10.0;
  localparam int ID_WIDTH = 4;

  // ---------------- masters ----------------
  localparam int M_CPU = 0;
  localparam int M_GPU = 1;
  localparam int M_NPU = 2;
  localparam int M_VDEC = 3;
  localparam int M_PQ = 4;
