  // ---------------- NoC slave ports ----------------
  localparam int S_DRAM0 = 0;
  localparam int S_DRAM1 = 1;
  localparam int S_DRAM2 = 2;
  localparam int S_DRAM3 = 3;
  localparam int S_DRAM4 = 4;
  localparam int S_DRAM5 = 5;
  localparam int S_DRAM6 = 6;
  localparam int S_DRAM7 = 7;
  localparam int S_BOOT_SRAM = 8;   // memory
  localparam int S_PERIPH = 9;   // apb_bridge
  localparam int S_APB = 9;
  localparam int S_DRAM_FIRST = 0, DRAM_NCH = 8;

  localparam string M_NAME [NM] = '{ "cpu", "gpu", "npu", "vdec", "pq", "disp", "hdmirx", "tsd", "adsp", "dma", "sec", "netio" };
  localparam string S_NAME [NS+1] = '{ "dram0", "dram1", "dram2", "dram3", "dram4", "dram5", "dram6", "dram7", "boot_sram", "periph", "decerr" };
  localparam string S_KIND [NS+1] = '{ "channel", "channel", "channel", "channel", "channel", "channel", "channel", "channel", "memory", "apb_bridge", "default" };

  // ---------------- address map ----------------
  localparam logic [31:0] DRAM_BASE = 32'h80000000, DRAM_SIZE = 32'h7FFFFFFF + 1;
  localparam int DRAM_GRANULE_BITS = 12, DRAM_CH_BITS = 3, DRAM_HASH = 1;
  localparam int DRAM_ACCESS = 24;   // lpddr5, timing preset lpddr5-6400

  localparam logic [31:0] BOOT_SRAM_BASE = 32'h00000000, BOOT_SRAM_SIZE = 32'h00010000;
  localparam logic [31:0] PERIPH_BASE = 32'h10000000, PERIPH_SIZE = 32'h00020000;

  localparam logic [31:0] S_BASE [NS] = '{ 32'h80000000, 32'h80000000, 32'h80000000, 32'h80000000, 32'h80000000, 32'h80000000, 32'h80000000, 32'h80000000, 32'h00000000, 32'h10000000 };
  localparam int S_ACCESS [NS] = '{ 24, 24, 24, 24, 24, 24, 24, 24, 2, 4 };

  // dram: channel = off[14:12] ^ off[17:15], off = a - DRAM_BASE
  function automatic int tv8k_mesh_dram_channel(logic [31:0] a);
    logic [31:0] off = a - DRAM_BASE;
    logic [2:0] c = off[14:12] ^ off[17:15];
    return int'(c);
  endfunction
  // channel-local address: the offset with the channel-select bits removed
  function automatic logic [31:0] tv8k_mesh_dram_local(logic [31:0] a);
    logic [31:0] off = a - DRAM_BASE;
    return ((off >> 15) << 12) | (off & 32'h00000FFF);
  endfunction
  function automatic int dram_channel(logic [31:0] a); return tv8k_mesh_dram_channel(a); endfunction
  function automatic logic [31:0] dram_local(logic [31:0] a); return tv8k_mesh_dram_local(a); endfunction

  // address -> NoC slave port (S_DEF on a miss)
  function automatic int tv8k_mesh_decode(logic [31:0] a);
    if (a >= DRAM_BASE && a - DRAM_BASE < 33'(DRAM_SIZE))
      return S_DRAM_FIRST + tv8k_mesh_dram_channel(a);
    if (a >= BOOT_SRAM_BASE && a - BOOT_SRAM_BASE < BOOT_SRAM_SIZE) return S_BOOT_SRAM;
    if (a >= PERIPH_BASE && a - PERIPH_BASE < PERIPH_SIZE) return S_PERIPH;
    return S_DEF;
  endfunction

  // ---------------- APB slots (periph) ----------------
  localparam logic [31:0] APB_BASE = 32'h10000000;
  localparam int APB_SLOT_BITS = 5;          // PADDR[16:12]
