  localparam int M_Y [NM] = '{ 1, 1, 2, 2, 2, 1, 2, 1, 1, 1, 1, 1 };
  localparam int S_X [NS] = '{ 0, 1, 2, 3, 0, 1, 2, 3, 1, 0 };
  localparam int S_Y [NS] = '{ 0, 0, 0, 0, 3, 3, 3, 3, 1, 2 };
  // XY hops, master m to slave port s
  localparam int HOPS [NM][NS] = '{
    '{ 2, 1, 2, 3, 3, 2, 3, 4, 0, 2 },   // cpu
    '{ 3, 2, 1, 2, 4, 3, 2, 3, 1, 3 },   // gpu
    '{ 3, 2, 3, 4, 2, 1, 2, 3, 1, 1 },   // npu
    '{ 4, 3, 2, 3, 3, 2, 1, 2, 2, 2 },   // vdec
